  'settings.reconnect.offState': 'Uudelleenyhdistäminen on pois päältä. Mikään ei pyydä reitittimeltä uutta osoitetta, ja hosterin raja jää tavallisen yritysten välisen odotuksen varaan.',

  'settings.reconnect.command': 'Ohjelma',
  'settings.reconnect.commandHint': 'Käynnistettävän ohjelman koko polku. Se käynnistetään suoraan eikä komentotulkin kautta, joten putki, uudelleenohjaus tai kaksi komentoa peräkkäin kuuluvat tapaan ”Skripti”. %%router%%, %%username%%, %%password%% ja %%ip%% täytetään ennen käynnistystä.',
  'settings.reconnect.args': 'Argumentit',
