  'settings.reconnect.upnpState': 'Muuta ei tarvita. Yhdyskäytävä löytyy verkolta kysymällä, ja juuri se tekee tästä sen tavan, joka toimii tietämättä reitittimestä yhtään mitään.',
  'settings.reconnect.upnpLocation': 'Yhdyskäytävän kuvaus-URL',
  'settings.reconnect.upnpLocationHint': 'Valinnainen ja tavallisesti tyhjä. Täytä vain siellä, missä monilähetyshaku suodatetaan pois mutta itse yhdyskäytävä on aivan hyvin tavoitettavissa, mitä pelkkä etsintä ei koskaan pysty korjaamaan.',

  'settings.reconnect.interpreter': 'Tulkki',
