  'settings.reconnect.interpreterArgs': 'Tulkin argumentit',
  'settings.reconnect.interpreterArgsHint': 'Yksi riviä kohti, sijoitetaan ennen skriptitiedostoa. Yleensä tyhjä.',
  'settings.reconnect.script': 'Skripti',
  'settings.reconnect.scriptHint': 'Kirjoitetaan yksityiseen väliaikaistiedostoon, ja tulkille annetaan sen polku, joten mikään täältä ei koskaan päädy lainausmerkkeihin komentoriville. Muuttujat täytetään ennen kuin tiedosto kirjoitetaan, eli tähän kenttään kirjoitettu salasana päätyy siihen tiedostoon: %%password%% pitää sen salasanakentässä.',

  'settings.reconnect.router': 'Reitittimen osoite',
