  'settings.reconnect.requests': 'Pyynnöt',
  'settings.reconnect.requestsHint': 'Toistetaan järjestyksessä, ja ajo pysähtyy ensimmäiseen, johon reititin ei vastaa. Tämä on JDownloaderin LiveHeader-tapa: yleensä kirjautuminen ja sitten uudelleenkäynnistys tai yhteyden katkaisu. Jokainen kenttä ottaa muuttujat.',
