  'settings.reconnect.checkTitle': 'Osoitteen tarkistus',
  'settings.reconnect.checkUrl': 'IP-tarkistuksen URL',
  'settings.reconnect.checkUrlHint': 'Haetaan ennen tavan suoritusta ja uudelleen sen jälkeen; ajo katsotaan valmiiksi heti, kun sen tulostama osoite on muuttunut. Oletusta ei ole tahallaan: itse ylläpidetyn latausohjelman ei pidä alkaa ilmoittaa osoitettasi palvelulle, jota et ole koskaan valinnut. Tulostuvan osoitteen on oltava se, jonka internet näkee, sillä sivu joka kertoo oman verkkosi osoitteen ei erota uudelleenyhdistämistä siitä, ettei mitään tapahtunut.',
  'settings.reconnect.checkPresets': 'Tunnetut palvelut',
  'settings.reconnect.checkPresetsHint': 'Oikopolku sille, jolla ei ole mieltymystä, ei oletusarvo: yhtäkään näistä ei valita puolestasi, ja mikä tahansa sivu joka tulostaa julkisen osoitteesi kelpaa yhtä hyvin.',
  'settings.reconnect.interval': 'Sekunteja tarkistusten välillä (1-60)',
  'settings.reconnect.intervalHint': 'Kuinka kauan odotetaan kahden tarkistus-URL:n katsomisen välillä sen jälkeen, kun tapa on suoritettu. Alaraja on olemassa siksi, että silmukka ilman sitä tekee tarkistuspalvelusta maalitaulun.',
  'settings.reconnect.timeout': 'Sekunteja tarkistusta (5-900)',
  'settings.reconnect.timeoutHint': 'Kuinka kauan katsotaan, ennen kuin ajoa kutsutaan epäonnistuneeksi. Uudelleenyhdistäminen, joka vartin päästä yhä odottaa, on epäonnistunut, sanottiin tässä mitä hyvänsä. Aikakatkaisu, joka alittaa välin, nostetaan siihen, tai ajo olisi ohi ennen kuin yhtäkään tarkistusta ehti tapahtua.',
