  'settings.chunks': 'Yhteyksiä latausta kohti (0 = automaattinen)',
  'settings.chunksHint': 'Kuinka monta yhteyttä yksi lataus avaa, kun mikään tarkempi ei päde. Sääntö tai yksittäinen lataus voi ilmoittaa oman lukunsa ja ohittaa tämän. Palvelu, joka sietää vähemmän, saa silti vähemmän: palvelun raja voi vain laskea lukua, ei koskaan nostaa sitä. Nollalla päätöksen tekee sovellus. Kourallista suurempi määrä yhteyksiä ei tuo mitään palvelussa, joka rajoittaa tiedostokohtaisesti, ja on varma tapa saada tili merkityksi.',
