  'props.mixedHint': 'Nämä rivit eivät ole yhtä mieltä, siksi kenttä on tyhjä. Koskematta se ei muuta mitään; kirjoita siihen, ja jokainen valittu rivi saa kirjoittamasi.',
  'props.name': 'Nimi',
  'props.nameHint': 'Yksi tiedostonimi, ei koskaan polku: kaikki, mikä kirjoittaa kansioita auki, lyhennetään yhdeksi nimeksi. Valmis lataus nimetään uudelleen myös levyllä, jotta lista ja kansio eivät voi olla eri mieltä. Käynnissä oleva pitää tiedoston, joka sen taustaosalla on auki, ja ottaa uuden nimen valmistuessaan. Aloittamaton ottaa sen heti. Nimi kuuluu yhdelle tiedostolle, joten tämä kenttä tarjotaan vain yhdelle riville.',
  'props.comment': 'Kommentti',
