  'settings.scripts.subtitle': 'Automatisoi KnightLoader omalla JavaScriptilläsi, joka suoritetaan tapahtumassa tai pyynnöstä.',
  'settings.scripts.listTitle': 'Omat skriptisi',
  'settings.scripts.add': 'Lisää skripti',
