  'settings.scripts.loadFailed':
    'Skriptejä ei voitu ladata. Jos tässä buildissa ei vielä ole automaatiomoottoria, tällä sivulla ei ole vielä mitään näytettävää - yritä uudelleen, kun se on.',
  'settings.scripts.name': 'Nimi',
