    'Mikä käynnistää tämän skriptin. Manuaalinen suoritetaan vain, kun pyydät sitä - alla olevasta Testiajosta, tai kohdasta ”Suorita skripti”, jonka tämä aalto lisää latauslistan oikean napin valikkoon.',
