  'settings.access.relay.title': 'Projektin välitin',
  'settings.access.relay.body': 'Välittäjä on välikäsi, jonka ansiosta kaikki instanssisi ovat tavoitettavissa kotiverkon ulkopuolelta, siis mistä tahansa. Tämän tarjoaa projekti maksutta.',
  'settings.access.relay.use': 'Käytä projektin välitintä',
  'settings.access.relay.leadProject': 'Toimii ilman asetuksia. Kaikki, mitä instanssisi sanovat toisilleen, on salattua, ja avain on vain sinulla.',
  'settings.access.relay.address': 'Osoite',
  'settings.access.relay.seesButton': 'Mitä se näkee?',
  'settings.access.relay.seesTip': 'Välityspalvelin ei näe: linkkejäsi, latauksiasi, tiedostojasi eikä käyttötunnistettasi.\n\nVälityspalvelin näkee: instanssiesi IP-osoitteet ja milloin ne lähettävät jotain.\n\nSitä ei saa salattua pois. Jos se häiritsee, pystytä oma välityspalvelin.',
  'settings.access.relay.none': 'Ei välitintä',
  'settings.access.relay.noneHint': 'Yksikään välittäjä ei ole käytössä. Samassa verkossa, siis kotiverkossasi, instanssit löytävät edelleen toisensa itse. Eri verkkojen välillä ne eivät tavoita toisiaan, joten etäkäyttöä ei ole.',
  'settings.access.relay.own': 'Oma välitin',
  'settings.access.relay.project': 'Projektin välitin',
  'settings.access.relay.whichHint': 'Kulkee osoitteen {address} kautta',
  'settings.access.relay.savedProject': 'Projektin välitin on käytössä',
  'settings.access.relay.savedOwn': 'Oma välittimesi on käytössä',
  'settings.access.relay.savedOff': 'Välitin kytketty pois',
  'settings.access.ownRelay.title': 'Oma välitin',
  'settings.access.ownRelay.body': 'Aja oma välittäjä projektin välittäjän sijaan.',
  'settings.access.ownRelay.use': 'Käytä omaa välitintäni',
  'settings.access.ownRelay.lead': 'Kaksi tapaa: tämä instanssi hoitaa välittimen, tai annat osoitteen.',
  'settings.access.ownRelay.serveLabel': 'Käytä tätä instanssia välittäjänä',
  'settings.access.ownRelay.serveHint': 'Toimii vain, jos tämä instanssi on tavoitettavissa ulkoa, esimerkiksi Nginx Proxy Managerin ja oman verkkotunnuksen kautta.',
  'settings.access.ownRelay.serveClients': '{count} yhteydessä juuri nyt.',
  'settings.access.ownRelay.addressLabel': 'Osoite',
  'settings.access.ownRelay.addressPlaceholder': 'esim. https://relay.omadomain.fi',
  'settings.access.ownRelay.save': 'Tallenna',
  'settings.access.ownRelay.everyInstance': 'Tämä osoite koskee vain tätä instanssia. Syötä se jokaiseen instanssiin.',
  'settings.access.ownRelay.containerLabel': 'Omana säiliönä',
  'settings.access.ownRelay.containerHint': 'Jos yksikään instanssisi ei ole tavoitettavissa ulkoa, välittäjän on oltava muualla: palvelimellasi tai pienellä VPS:llä. Asenna kontti Unraid Community Applications -kokoelmasta tai alla olevalla komennolla.\n\nKontti ei vaadi asetuksia: käynnistä, kirjoita sen osoite ylle, valmis. Se ei tallenna mitään, joten varmuuskopioitavaa ei ole.',
  'settings.access.tokens.title': 'API-tokenit',
  'settings.access.tokens.intro':
    'Nimettyjä tunnuksia skriptille, selainlaajennukselle tai puhelimelle. Kunkin voi peruuttaa erikseen, muuttamatta jaettua salasanaa, jota jokainen muu asiakas käyttää.',
  'settings.access.tokens.empty': 'Yhtään tokenia ei ole vielä myönnetty.',
