  'settings.access.tokens.secretWarning':
    'Tämä on ainoa kerta, kun tämä token näytetään. Se tallennetaan yksisuuntaisena tiivisteenä tähän instanssiin, joten jos se katoaa, sitä ei voi lukea uudelleen - vain mitätöidä ja luoda uusi.',
  'settings.access.tokens.copy': 'Kopioi',
