  'settings.access.tokens.createFailed': 'Tokenia ei voitu luoda: {error}',
  'settings.access.identity.title': 'Tämän instanssin identiteetti',
  'settings.access.identity.nameLabel': 'Nimi',
  'settings.access.identity.namePlaceholder': 'esim. Kotipalvelin',
  'settings.access.identity.nameHint': 'Tarjotaan ensin pariliitosta muodostettaessa ja alla olevassa QR-koodissa, sen sijaan mitä käyttöjärjestelmä tai container-ajonaikainen ympäristö sattuu kutsumaan tätä konetta. Valinnainen - jätä tyhjäksi, jos haluat käyttää sitä edelleen.',
  'settings.access.identity.domainsLabel': 'Tunnetut verkkotunnukset',
  'settings.access.identity.domainsHint': 'Muistetaan automaattisesti heti kun pyyntö todella saapuu sen kautta, joten se pysyy tässä listattuna, vaikka myöhemmät pyynnöt saapuisivatkin sen sijaan lähiverkon IP:n kautta. Lisää yksi käsin verkkotunnukselle, joka on jo määritetty mutta jonka kautta ei ole vielä vierailtu - yksi täydellinen osoite riviä kohden, esim. https://kl.example.com.',
  'settings.access.cardTitle': 'Yhdistä instanssit ja etäkäyttö',
  'settings.access.phrase.body': 'Yksi lause yhdistää kaikki KnightLoaderisi. Luo se tässä ja liitä muihin instansseihin - ei tiliä, ei kirjautumista, ei mitään määritettävää.',
  'settings.access.phrase.noPasswordWarning': 'Tällä instanssilla ei ole salasanaa. Lause avaa jokaisen instanssin, jonka sillä yhdistät, joten kuka tahansa sen tässä lukeva pääsee kaikkiin, ei vain tähän. Aseta mieluummin ensin salasana yllä.',
  'settings.access.phrase.activate': 'Luo lause',
  'settings.access.phrase.howLead': 'Kaksitoista sanaa, siinä kaikki. Näin se käy, ja tätä tapahtuu:',
  'settings.access.phrase.howStep1': 'Paina tässä instanssissa "{button}". Näkyviin tulee kaksitoista sanaa.',
  'settings.access.phrase.howStep2': 'Avaa KnightLoader toisella koneella, tule tälle samalle sivulle, paina "{button}" ja kirjoita kaksitoista sanaa.',
  'settings.access.phrase.howStep3': 'Valmis! Kumpikin instanssi näkyy nyt toisen kohdalla ”Instanssit”-sivulla, ja voit ohjata kumpaa tahansa kummasta tahansa. Välityspalvelimen ollessa päällä instanssisi ovat tavoitettavissa verkkosi ulkopuolelta.',
  'settings.access.phrase.howWhat': 'Sanat ovat salaisuus, ei osoite. Jokainen instanssi laskee niistä kaksi avainta: toisen muiden löytämiseen, toisen salaamiseen.\n\nLöytääkseen toisensa jokainen instanssi soittaa itse samaan kohtaamispaikkaan internetissä. Se, joka näyttää saman avaimen, yhdistetään. Siksi yhdenkään instanssisi ei tarvitse olla tavoitettavissa ulkoa.\n\nKohtaamispaikka ei voi lukea mukana. Se ei näe sanojasi koskaan, ja kaikki sen läpi kulkeva on salattu toisella avaimella.',
  'settings.access.phrase.statusDisconnected': 'Ei yhdistetty',
  'settings.access.phrase.statusHintProject': 'Yhdistetty projektin välittäjään. Etäkäyttö on valmis.',
  'settings.access.phrase.statusHintOwn': 'Yhdistetty omaan välittäjääsi. Etäkäyttö on valmis.',
  'settings.access.phrase.statusHintOff': 'Yksikään välittäjä ei ole käytössä. Instanssisi tavoittaa vain lähiverkossa.',
  'settings.access.phrase.statusHintLost': 'Ei yhteyttä välittäjään. KnightLoader yrittää edelleen. Siihen asti instanssit tavoittavat toisensa vain lähiverkossa.',
