  'settings.nav.browsertools': 'Selain ja sovellus',
  'settings.browsertools.bookmarkletStep1': 'Vedä alla oleva painike selaimesi kirjanmerkkipalkkiin - se tallentuu kuten mikä tahansa muu kirjanmerkki, mitään ei asenneta.',
  'settings.browsertools.bookmarkletStep2': 'Napsauta sitä millä tahansa sivulla (valitse ensin tekstiä, jos haluat vain sen). Pieni KnightLoader-välilehti avautuu kyseisen sivun linkillä tai valitulla tekstillä valmiiksi täytettynä - tarkista se ja lisää se sieltä latauksena.',
  'settings.browsertools.installLabel': 'Näin asennat sen',
