  'settings.nav.resolvers': 'Ratkaisijat',
  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Moduuli ei ole käytettävissä',
  'settings.resolvers.moduleUnavailableHint': 'Kaikki alla tallentuu silti ja astuu voimaan heti, kun yt-dlp tulee saataville - mikään ei katoa, vaikka muokkaisit jo nyt.',
  'settings.resolvers.intro': 'Asetukset yt-dlp-taustajärjestelmälle, joka noutaa media- ja suoratoistosivustot, joita yt-dlp itse tukee. Se, mikä palvelu ylipäätään käsittelee tietyn linkin - yt-dlp, debrid-tili, pääteohjelmaton JD-sivukärry - päätetään Tilit-sivun reititysjärjestyksessä; tämä koskee vain sitä, mitä yt-dlp tekee, kun linkki on jo ohjattu sille.',
  'settings.resolvers.quality': 'Laatu',
  'settings.resolvers.qualityHint': 'Mikä -f-valitsin annetaan yt-dlp:lle käynnistettäessä. Paras saatavilla on yt-dlp:n oma oletus ja se, mitä jokainen lataus käytti ennen tätä asetusta.',
  'settings.resolvers.quality.best': 'Paras saatavilla',
