  'settings.resolvers.customFormat': 'Oma formaatti',
  'settings.resolvers.customFormatHint': 'yt-dlp:n oma -f-arvo, esim. bestvideo[height<=720]+bestaudio/best. Välitetään tarkistamatta; arvo, jonka yt-dlp hylkää, epäonnistuu sen omaan virheeseen tehtävässä.',
  'settings.resolvers.playlist': 'Lataa koko soittolista, kun linkki osoittaa sen sisään',
  'settings.resolvers.subtitles': 'Tekstitykset',
  'settings.resolvers.subtitleLangs': 'Kielet',
  'settings.resolvers.subtitleLangsHint': 'yt-dlp:n oma --sub-langs-arvo, esim. en,de. Tyhjä tarkoittaa oletusta en.',
  'settings.resolvers.subtitleAuto': 'Nouda myös automaattisesti luodut tekstitykset, kun manuaalista raitaa ei ole',
  'settings.resolvers.outputTitle': 'Tulostiedoston nimi',
  'settings.resolvers.outputHint': 'yt-dlp:n oma -o-malli. Tyhjä käyttää sisäänrakennettua %(title)s.%(ext)s. Voi sisältää alikansioita, esim. %(uploader)s/%(title)s.%(ext)s.',

  'settings.nav.torrents': 'Torrentit',
  'settings.module.torrents': 'Torrentit',
  'settings.torrents.title': 'Torrentit',
  'settings.torrents.subtitle': 'Jakotavoitteet, siirtorajat, portin uudelleenohjaus ja DHT/PEX magnet-linkeille ja .torrent-tiedostoille.',
  'settings.torrents.seedingTitle': 'Jakaminen',
  'settings.torrents.seedRatio': 'Jaon tavoitesuhde',
  'settings.torrents.seedRatioHint': 'Jatkaa valmiin torrentin jakamista, kunnes tämä osuus sen omasta koosta on annettu takaisin parville. 0 = ei ratiotavoitetta.',
  'settings.torrents.seedDuration': 'Jaon tavoitekesto',
  'settings.torrents.seedDurationHint': 'Jatkaa valmiin torrentin jakamista näin kauan valmistumisen jälkeen. 0 = ei aikarajaa. Kumpi tahansa yllä olevista tavoitteista saavutetaan ensin, pysäyttää jakamisen.',
  'settings.torrents.seedDurationUnit': 'tuntia',
  'settings.torrents.transferTitle': 'Siirtoraja',
  'settings.torrents.uploadLimit': 'Lähetysraja',
  'settings.torrents.uploadLimitHint': 'Rajoittaa, kuinka nopeasti torrent lähettää dataa parville jakamisen aikana. 0 = rajoittamaton.',
  'settings.torrents.uploadLimitUnit': 'KiB/s',
  'settings.torrents.portTitle': 'Portti ja uudelleenohjaus',
  'settings.torrents.port': 'Portti',
  'settings.torrents.portHint': 'Portti, jota tämä instanssi kuuntelee parven yhteyksiä varten. 0 antaa torrent-moottorin valita sen itse.',
  'settings.torrents.portMapHint': 'Pyytää reititintä ohjaamaan yllä olevan portin tähän koneeseen UPnP:n kautta, jotta toisen reitittimen takana olevat peerit voivat silti tavoittaa sen. Kaikki reitittimet eivät tue tätä, ja jotkin hyväksyvät pyynnön ilman että se todella toimii.',
  'settings.torrents.portMapButton': 'Kokeile UPnP-uudelleenohjausta',
  'settings.torrents.portMapping': 'Kysytään reitittimeltä…',
  'settings.torrents.portMapNeedsPort': 'Aseta portti yllä ennen sen ohjaamista - arvolla 0 reitittimellä ei ole minne ohjata.',
  'settings.torrents.portMapConfirmed': 'Vahvistettu: portti {port} on ohjattu ja sen tavoitettavuus on todennettu.',
  'settings.torrents.portMapUnconfirmed': 'Reititin hyväksyi pyynnön, mutta ei voitu vahvistaa, että uudelleenohjaus todella toimii. Jotkin reitittimet tekevät tämän hiljaa - kokeile yhteystarkistusta verkon ulkopuolelta.',
  'settings.torrents.portMapFailed': 'Portin ohjaaminen epäonnistui: {error}',
  'settings.torrents.portMapUnavailable': 'Tämä versio ei vielä tarjoa portin uudelleenohjausta.',
  'settings.torrents.networkTitle': 'Peerien haku',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Löytää peerejä ilman trackeria käyttämällä muita BitTorrent-asiakasohjelmia hajautettuna hakemistona.',
  'settings.torrents.pex': 'Peer exchange (PEX)',
  'settings.torrents.pexHint': 'Vaihtaa tunnettuja peerejä jo yhdistettyjen kanssa, jotta parvi, jossa on vähän peerejä, löytyy nopeammin.',
  'settings.torrents.privateNote': 'Yksityinen torrentti poistaa molemmat käytöstä automaattisesti heti, kun sen metatiedot tunnetaan, riippumatta tämän asetuksesta - ladatun .torrent-tiedoston kohdalla heti, magnet-linkin kohdalla heti, kun sen omat metatiedot saapuvat parvelta. Useimmat yksityiset trackerit bannaavat tilit, jotka käyttävät jompaakumpaa.',
  'settings.torrents.engineNote': 'Jaon tavoitesuhde, jaon tavoitekesto ja portti vaikuttavat nyt jokaiseen torrenttiin, jonka tämä moottori käynnistää - portti tosin vain kaikkein ensimmäiseen tämän instanssin viime uudelleenkäynnistyksen jälkeen, koska moottorin oma torrent-asiakasohjelma rakennetaan vain kerran eikä sitä enää rakenneta uudelleen sen jälkeen; myöhempi tallennus tallentuu silti oikein ja astuu voimaan seuraavasta uudelleenkäynnistyksestä alkaen. Lähetysraja vain tallennetaan ja tarkistetaan edelleen, eikä moottorilla ole vielä keinoa viedä sitä käynnissä olevaan lataukseen. Alla olevat DHT ja PEX ovat samassa tilanteessa tavallisen (ei-yksityisen) torrentin kohdalla: tämän instanssin oma oletusarvo ei myöskään vielä ulotu käynnissä olevaan lataukseen, joten torrentti jatkaa jakamista molempien ollessa päällä riippumatta tämän asetuksesta - yksityinen torrentti on täysin eri tapaus, katso alempana oleva huomautus. Alempana oleva uudelleenohjauspainike tekee silti jotain todellista: se pyytää rehellisesti reititintä ohjaamaan yllä syötetyn porttinumeron, riippumatta siitä, kuunteleeko sitä juuri nyt mikään torrent.',
  'torrent.staging': 'Lisätään…',
