  'onboarding.step': 'Vaihe {n}/{total}',
  'onboarding.skip': 'Ohita',
  'onboarding.back': 'Takaisin',
  'onboarding.next': 'Seuraava',
  'onboarding.finish': 'Aloita KnightLoaderin käyttö',
  'onboarding.welcome.title': 'Tervetuloa KnightLoaderiin',
  'onboarding.welcome.body': 'KnightLoader on itse ylläpidetty latauksenhallinta: liitä tai pudota linkki, ja sen noutaa mikä tahansa taustajärjestelmä, joka sen oikeasti käsittelee - sisäänrakennettu moottori tavallisille tiedostolinkeille, yt-dlp mediasivuille, debrid-palvelu isännille, joille jo maksat, tai pääkäytön JDownloader kaikelle muulle. Tämä lyhyt esittely kattaa sen yhden asetuksen, joka kannattaa tarkistaa ennen aloittamista.',
  'onboarding.welcome.langLabel': 'Käyttöliittymän kieli',
  'onboarding.folder.title': 'Minne tiedostojen pitäisi päätyä?',
  'onboarding.folder.body': 'Tämä on kansio, johon valmiit lataukset kirjoitetaan. Kirjoita polku tai selaa palvelinta löytääksesi sellaisen - voit vaihtaa sen milloin tahansa uudelleen Yleiset-asetuksista.',
  'onboarding.accounts.title': 'Premium-isännät, silloin kun haluat',
  'onboarding.accounts.body': 'Jono toimii ilman tiliä. Kun haluat täyden nopeuden isännältä tai debrid-palvelulta, jolle jo maksat, lisää sen kirjautumistiedot Tileihin - tänne ei tarvitse asettaa mitään juuri nyt.',
  'onboarding.accounts.link': 'Avaa Tilit',
  'onboarding.finished.title': 'Olet valmis',
  'onboarding.finished.body': 'Siihen esittely päättyy. Asetusten Ohje-sivulla on täydellinen läpikäynti kaikesta muusta, mitä tämä versio tekee, ja useimmilla säätimillä on oma selityksensä (i)-kuvakkeen takana.',

