  'settings.nav.shortcuts': 'Pikanäppäimet',
  'settings.shortcuts.subtitle': 'Kaikki komennot, joilla on oletuspikanäppäin, ryhmiteltynä käyttöalueen mukaan. Vaihda sidontaa, tai palauta se oletukseksi.',
