  'settings.headerProfiles.title': 'Otsakeprofiilit',
  'settings.headerProfiles.hint': 'Jotkin sivustot luovuttavat tiedoston vain selaimelle, joka on kirjautunut sisään, tai vain silloin, kun kutsu tulee niiden omalta sivulta. Profiili tallentaa otsakkeet täsmälleen yhtä sivustoa varten, salattuna samalla tavalla kuin tiliavaimesi, ja KnightLoader lähettää ne mukana jokaisessa latauksessa tuolta sivustolta.',
  'settings.headerProfiles.empty': 'Ei vielä otsakeprofiileja.',
