  'settings.rules.action.category': 'Kategoria',
  'settings.rules.action.categoryHint': 'Lajittelee osuvat linkit johonkin Kategoriat-sivun laatikoista, joka tuo mukanaan oman kansionsa, oman paikkansa jonossa, oman purkukytkimensä ja oman törmäyssääntönsä. Muuttamattomana yhdelläkään säännöllä ei ole asiasta mielipidettä ja linkki jää lajittelematta. Jos tämä sääntö nimeää lisäksi latauskansion, se kansio voittaa, ja laatikko tuo silti kaiken muun. Poistetun laatikon nimeäminen hylätään tallennettaessa, sillä sääntö, joka osoittaa laatikkoon jota ei ole, ei tee jokaisen osuvan linkin kohdalla yhtään mitään, ilman mitään ilmoitusta.',
