  'detail.retries': 'Uudelleenyrityksiä tähän mennessä',
  'detail.retriesHint': 'Kuinka usein tätä latausta on yritetty uudelleen epäonnistumisen jälkeen. Laskuri palautetaan nollaan sillä hetkellä, kun lataus valmistuu, joten valmis rivi näyttää nollaa silloinkin, kun siihen meni neljä yritystä. Sitä, montako yritystä on jäljellä, ei näytetä: katto riippuu syystä ja hosterista, eikä tämä sivu osaa laskea sitä.',
  'detail.stallRestarts': 'Uudelleenaloitukset pysähdyksen jälkeen',
