  'detail.failure': 'Mikä meni pieleen',
  'detail.cause': 'Syy',
  'detail.message': 'Mitä taustaosa sanoi',
  'detail.messageHint': 'Sen lause, joka yritti hakea tämän, sanasta sanaan ja kääntämättä. Se on nykyinen virhe eikä mitään muuta: uudelleenaloitus pyyhkii sen, eikä sitä edeltäneistä jää mitään talteen.',
  'detail.heldBack': 'Mikä pidättää',
  'detail.doing': 'Tekee juuri nyt',
  'detail.filtered': 'Linkkisuodattimen pidättämä',
  'detail.gaveUp': 'Ei uutta yritystä',
  'detail.gaveUpHint': 'Tähän on lopetettu tahallaan, ei siksi että yritykset loppuivat: captcha, täysi levy tai sääntö, joka sanoo tälle hosterille ”ei koskaan”. Uudelleenyritysten määrän nostaminen ei muuta tässä mitään. Itse merkintää ei kirjoiteta tietokantaan, joten uudelleenkäynnistyksen jälkeen se on poissa, vaikka sen syy ei ole.',
  'detail.rules': 'Säännöt, jotka muovasivat tätä',
  'detail.rulesHint': 'Säännöt, jotka laukesivat tähän linkkiin sitä valmisteltaessa, siinä järjestyksessä kuin ne laukesivat. Ne säilytetään nimellä, joten sen jälkeen uudelleen nimettyä sääntöä ei enää löydetä, ja sääntö, jolla ei koskaan ollut nimeä, säilytetään sillä sijainnilla, joka sillä silloin oli. Napsautus avaa sen sääntömuokkaimessa.',
  'detail.openRule': 'Avaa sääntömuokkaimessa',
