  'notifications.title': 'Ilmoitukset',
  'notifications.titleHint': 'Päätä tapahtumakohtaisesti, näkyykö se ilmoituksena sovelluksessa, käyttöjärjestelmäsi ilmoituksena vai ei lainkaan. Järjestelmän ilmoitus tavoittaa sinut vain niin kauan kuin jokin KnightLoader-välilehti on auki, ja alla oleva hiljainen tila pätee tämän lisäksi.',
  'notifications.channel.app': 'Sovelluksessa',
