  'notifications.event.downloadDone': 'Lataus valmis',
  'notifications.event.downloadDoneHint': 'Jokainen lataus, joka pääsee loppuun asti, ilmoittaa siitä. Kaksisataa tiedostoa jonossa tarkoittaa kahtasataa tällaista ilmoitusta, joten mieti kahdesti, ennen kuin lähetät ne järjestelmään.',
  'notifications.event.downloadFailed': 'Lataus epäonnistui',
  'notifications.event.downloadFailedHint': 'Lataus, joka on luovuttanut. Hiljainen tila ei piilota tätä koskaan.',
  'notifications.event.extractionDone': 'Purkaminen valmis',
  'notifications.event.extractionDoneHint': 'Arkisto, joka on purettu valmiiksi. Tästä ei ole aiemmin ilmoitettu missään, joten se on aluksi kohdassa ”Älä näytä mitään”.',
  'notifications.event.extractionFailed': 'Purkaminen epäonnistui',
  'notifications.event.extractionFailedHint': 'Arkisto, joka pysähtyi kesken. Yleensä salasana puuttuu, ja tiedostot jäävät paikoilleen, kunnes hoidat asian.',
  'notifications.event.captchaWaiting': 'Captcha odottaa',
  'notifications.event.captchaWaitingHint': 'Captcha-ikkuna aukeaa tässä välilehdessä joka tapauksessa. Se on aluksi kohdassa ”Älä näytä mitään”, koska tuo ikkuna on jo itsessään se ilmoitus, niin kauan kuin katsot sitä. Aseta se järjestelmän ilmoitukseksi, niin taustavälilehdessä oleva captcha tavoittaa sinut ennen kuin hosteri heittää istunnon pois.',
  'notifications.event.captchaFailed': 'Captcha epäonnistui',
  'notifications.event.captchaFailedHint': 'Kukaan ei vastannut ajoissa, tai vastaus ei mennyt perille. Sen takana oleva lataus jää paikoilleen.',
  'notifications.event.captchaResolved': 'Captcha ratkaistiin muualla',
  'notifications.event.captchaResolvedHint': 'Joku toisessa selaimessa tai automaattinen ratkaisija vastasi siihen, ja ikkuna sulkeutui itsestään.',
  'notifications.systemUnavailable': 'Järjestelmän ilmoituksia ei ole täällä käytettävissä: selaimesi tarjoaa niitä vain HTTPS:n yli tai localhostissa. Kaikki tällä kortilla näkyy silti sovelluksessa.',
  'notifications.systemBlocked': 'Selaimesi estää ilmoitukset tälle osoitteelle. Rivit, joissa on ”Järjestelmän ilmoitus”, näkyvät sen sijaan sovelluksessa, kunnes sallit ne uudelleen selaimesi sivustoasetuksissa.',
  'notifications.systemNotGranted': 'Selain ei antanut lupaa, joten tämä tapahtuma pysyy sovelluksessa. Valitse ”Järjestelmän ilmoitus” uudelleen, niin kysytään toistamiseen.',
