  'views.clearAllHint': 'Haku ja suodattimet jäävät voimaan, kun poistut sivulta ja palaat takaisin, joten näet taas sen listan, jonka jätit. Tämä palauttaa koko listan. Tallennettuihin näkymiin ei kosketa.',

  'disk.title': 'Kohdekansiot',
  'disk.hint': 'Vapaa ja käytetty tila jokaisessa kansiossa, johon lataus voi päätyä, sekä se määrä, jonka jono aikoo vielä kirjoittaa kuhunkin. Luvut tulevat samasta kyselystä, jota vasten levytilarajat tarkistetaan, ja ovat korkeintaan muutaman sekunnin vanhoja. Vapaa ja käytetty eivät aina anna yhteen laskettuna taltion kokoa: tiedostojärjestelmä pitää siivun järjestelmää varten, ja käyttäjäkohtainen kiintiö voi jättää tälle instanssille vähemmän kuin taltiolla oikeasti on. Kaksi kansiota samalla levyllä näyttävät kumpikin saman levyn, joten älä koskaan laske rivejä yhteen.',
  'disk.free': 'Vapaa',
  'disk.used': 'Käytetty',
  'disk.size': 'Taltion koko',
  'disk.queued': 'Vielä kirjoitettavaa',
  'disk.queuedHint': 'Mitä vielä avoinna olevat lataukset kirjoittaisivat tähän kansioon: hosterin ilmoittama koko miinus se, mikä on jo saapunut. Lataus, jonka kokoa hosteri ei kerro, lasketaan tässä nollaksi, joten tämä on alaraja eikä koskaan lupaus, ja siksi kansion kohdalla voi lukea nolla tavua, vaikka vieressä on rivillinen latauksia. Pois kytketyt lataukset jäävät ulkopuolelle, sama sääntö kuin listan alla olevissa laskureissa. Lataus, joka on jo käynnissä, on yleensä saanut tilansa varatuksi levyltä heti käynnistyessään, joten sen tavut puuttuvat jo viereisestä vapaan tilan luvusta eivätkä tule sen päälle.',
  'disk.tasks': '{n} latausta',
  'disk.unknown': 'Tämä järjestelmä ei kerro vapaata tilaa',
  'disk.unknownHint': 'Jokaiselta ytimeltä ei voi kysyä, paljonko taltiolla on tilaa jäljellä, eikä tällä buildilla ole sopivaa kutsua sille, jonka päällä se ajaa. Siellä missä vastausta ei saada, mitään ei pidätetä: lataukset käynnistyvät täsmälleen kuten ennen levytilarajoja. Tämä rivi on tässä, jotta erotat sen levystä, joka on oikeasti täynnä.',
  'disk.missing': 'Ei vielä luotu',
  'disk.missingHint': 'Tämän kansion luo se, joka kirjoittaa siihen ensimmäisen tiedoston, joten sitä ei ole vielä olemassa. Luvut kuvaavat polkua {path}, joka on lähin sen yläpuolella oleva olemassa oleva kansio, ja se on sillä taltiolla, jolle lataus päätyisi.',
  'disk.measured': 'Mitattu kohteesta {path}',
  'disk.elsewhereHint': 'Itse kansiota ei voitu mitata, joten mitattiin lähin sen yläpuolella oleva, joka voitiin. Jos jokin liitos ei noussut ylös, kyseessä voi olla aivan eri levy kuin se, jolle lataus on tarkoitettu. Katso polku, ennen kuin päättelet luvuista mitään.',
  'disk.sampled': 'Luettu {n} sekuntia sitten',
  'disk.tight': 'Jono ei mahdu',
  'disk.tightHint': 'Tälle kansiolle on luvattu enemmän kuin taltiolla on vapaana. Tämä rivi ei yksin pysäytä mitään: pidättäminen tehdään yksi kerrallaan sitä mukaa kuin lataus tulee vuoroon, Lataukset-asetussivun lukujen mukaan, eikä lataus, jonka kokoa kukaan ei tiedä, laske tässä mukaan lainkaan.',
  'disk.truncated': 'Kaikki kansiot eivät ole tässä',
  'disk.truncatedHint': 'Jono tähtää useampaan asetettujen ulkopuoliseen kansioon kuin mitä kannattaa mitata jokaisella lukukerralla, joten ne, joille on luvattu vähiten, jätettiin pois. Jokainen asettamasi kansio on aina mukana.',
  'disk.markLow': 'Tämän alapuolella ei käynnisty mitään uutta',
  'disk.markStop': 'Tämän alapuolella kaikki pysähtyy',
  'disk.limits': 'Aseta levytilarajat',
  'disk.stripLabel': 'Tila kohdekansioissa',
  'disk.role.downloads': 'Latauskansio',
  'disk.role.category': 'Kategoriakansio',
  'disk.role.work': 'Työkansio',
  'disk.role.task': 'Asetettu latauksessa itsessään',

  'settings.volume.title': 'Datakatto',
  'settings.volume.titleHint': 'Mitä tämä instanssi on saanut ladattua valmiiksi, laskettuna asettamaasi kattoa vasten, jaksoa kohti. Mukaan lasketaan se koko, jonka hosteri ilmoitti kullekin valmiille lataukselle, joten kaikki ilman ilmoitettua kokoa valmistunut lasketaan nollaksi, eikä se, mitä torrent lähettää, laske mukaan lainkaan. Tämä on lukema latauksistasi, ei mittaus liittymästäsi: kukaan täällä ei näe niitä tavuja, jotka reitittimesi oikeasti liikutti.',
  'settings.volume.cap': 'Katto jaksoa kohti (GB)',
  'settings.volume.capHint': '0 tarkoittaa, ettei kattoa ole: laskuri käy edelleen eikä mitään koskaan pidätetä. Gigatavut ovat täällä kymmenjärjestelmän mukaisia, niin kuin operaattori ilmoittaa datamääränsä: 500 GB on 500 000 000 000 tavua eikä 465 GiB. Tämän sivun ylempänä olevat levyarvot ovat binäärisiä GiB-yksiköitä, eri yksikkö eri kysymykseen.',
  'settings.volume.resetDay': 'Laskuri alkaa alusta päivänä',
  'settings.volume.resetDayHint': 'Kuukauden päivä, jona laskuri palaa nollaan, yleensä se päivä, jona datamääräsi uusiutuu. Kuukaudessa, joka on lyhyempi kuin valitsemasi päivä, se alkaa alusta sen kuukauden viimeisenä päivänä eikä luiskahda koskaan seuraavaan. Lasketaan palvelimen kellon mukaan, ei selaimesi, sillä palvelin on se, joka pidättää jonoa.',
  'settings.volume.action': 'Kun katto tulee täyteen',
  'settings.volume.actionHint': 'Jo käynnissä olevaa siirtoa ei keskeytetä koskaan, valitsit minkä vastauksen tahansa: kesken tiedoston lopettaminen heittää pois tavut, jotka olet jo käyttänyt. ”Vain ilmoita” ei muuta mitään, jolloin laskuri on koko ominaisuus. ”Älä käynnistä uusia latauksia” antaa käynnissä olevan päättyä ja pidättää jonoa, kunnes laskuri alkaa alusta; jokainen odottava rivi myös kertoo sen. ”Hidasta kaikkea” pitää jonon käynnissä alla olevalla nopeudella.',
  'settings.volume.actionReport': 'Vain ilmoita',
  'settings.volume.actionPause': 'Älä käynnistä uusia latauksia',
  'settings.volume.actionThrottle': 'Hidasta kaikkea',
  'settings.volume.throttle': 'Nopeus katon jälkeen (KiB/s)',
  'settings.volume.throttleHint': 'Rajoitus, joka pätee jakson loppuun asti. Se on yksi katto muiden rajojesi rinnalla eikä koskaan niiden sijasta, joten yöllinen ikkuna tai hiljainen kytkin, jotka vaativat vähemmän, voittavat edelleen. 0 tarkoittaisi tässä, ettei rajaa ole lainkaan, ja se on sama asia kuin ettei kattoa olisi, joten pienin järkevä luku on 1.',
  'settings.volume.noCap': 'Ei kattoa',
  'settings.volume.used': 'Ladattu tällä jaksolla',
  'settings.volume.usedOf': '{used} / {cap}',
  'settings.volume.resetsOn': 'Alkaa alusta {date}',
  'settings.volume.reached': 'Katto on tullut täyteen.',

  'volume.title': 'Ladattu datamäärä',
  'volume.titleHint': 'Valmiit lataukset laskettuna yhteen päivittäin ja kuukausittain latausten historiasta. Historialla on oma ylärajansa ja sen voi tyhjentää käsin, joten kuukaudet, jotka ovat pudonneet sen perästä pois, eivät yksinkertaisesti ole täällä. Uudelleen aloittamasi lataus lasketaan kerran, sinä päivänä, jona se viimeksi valmistui. Kalenteri on palvelimen, aikavyöhykkeellä {zone}.',
  'volume.range.days': '30 päivää',
  'volume.range.months': '12 kuukautta',
  'volume.split.total': 'Kaikki',
  'volume.split.host': 'Hosterin mukaan',
  'volume.split.backend': 'Taustaosan mukaan',
  'volume.other': 'Kaikki muu',
  'volume.empty': 'Tällä aikavälillä ei ole vielä valmistunut mitään.',
  'volume.unsizedHint': 'Näistä latauksista {n} valmistui ilman että hosteri ilmoitti koskaan kokoa. Ne eivät kasvata summaa, joten todellinen luku on tässä piirrettyä suurempi.',
  'volume.trimmedHint': 'Historia on omassa rajassaan, joten kaikki sen vanhinta merkintää vanhempi puuttuu myös tästä käyrästä. Nosta historian ylärajaa tällä sivulla, jos haluat katsoa pidemmälle taaksepäin.',
  'volume.meter': 'Datamäärä',
  'volume.meterHint': 'Mitä on ladattu valmiiksi sen jälkeen, kun laskuri viimeksi alkoi alusta, mitattuna Lataukset-asetussivun kattoa vasten. Luku liikkuu, kun lataus valmistuu, ei sen ollessa käynnissä: se siis hyppii eikä ryömi. Se lasketaan yhteen latausten historiasta, joten historian tyhjentäminen nollaa myös tämän laskurin.',

