  'events.titleHint': 'Jokainen ilmoitus, jonka tämä ikkuna sinulle näyttää, päätyy myös tänne. Niin voit lukea sellaisenkin, jonka kupla on jo kadonnut. Tallessa pysyy viimeiset {max}, ja jokaisella sivun latauskerralla lista alkaa alusta.',
  'events.unread': '{n} lukematonta',
  'events.empty': 'Mitään ei ole vielä tapahtunut',
  'events.emptyHint': 'Mitä KnightLoader seuraavaksi kertoo, se ilmestyy tähän.',
