  'settings.diagnostics.fix.missing': 'Kansiota ei ole. Lähin olemassa oleva kansio sen yläpuolella on {measured}. Koneella, jolle on liitetty jako, se tarkoittaa useimmiten, ettei jako ole liitettynä. Täällä jätettiin tahallaan luomatta mitään: puuttuvan liitoksen alle tehty kansio ottaa lataukset vastaan, ja ne ovat seuraavassa konttipäivityksessä poissa.',
  'settings.diagnostics.fix.denied': 'Kansio on olemassa, eikä tämä instanssi saa kirjoittaa siihen. Kontissa KnightLoader ajaa tunnuksella uid 1000, joten kansion on kuuluttava tuolle käyttäjälle tai ryhmälle, jossa hän on.',
  'settings.diagnostics.fix.readonly': 'Tämän kansion alla oleva tiedostojärjestelmä on liitetty vain luettavaksi. Tämä instanssi ei voi sille mitään, liitos on muutettava.',
  'settings.diagnostics.fix.full': 'Taltiolla, jolla tämä kansio on, ei ole enää tilaa.',
  'settings.diagnostics.fix.notRemoved': 'Testitiedosto saatiin kirjoitettua, mutta ei enää poistettua. Lataus saapuisi tänne, eikä sitä saisi sen jälkeen koskaan nimettyä uudelleen tai siirrettyä pois tieltä. Katso kansion poisto-oikeutta, älä kirjoitusoikeutta.',
  'settings.diagnostics.fix.notADir': 'Tässä polussa on tiedosto, ei kansio.',
  'settings.diagnostics.fix.timeout': 'Kansio ei vastannut ajoissa ja se jätettiin rauhaan. Jako, jonka palvelin on pois päältä, käyttäytyy täsmälleen näin, ja niin käyttäytyy myös jako kadonneessa verkossa.',
  'settings.diagnostics.fix.dataDenied': 'Tämä on se yksi kansio, jota ilman instanssi ei tule toimeen: tietokanta, asetukset ja salattu tunnusvarasto ovat kaikki täällä. Lataukset jatkuvat toistaiseksi, ja seuraava tallennus menee hukkaan.',
  'settings.diagnostics.fix.javaMissing': 'Javaa ei löytynyt. Kontti-image tuo sellaisen mukanaan, työpöytäasennus käyttää mukana tulevaa Java-ajoympäristöä tai PATH-polulta löytyvää. Ilman Javaa yksityinen JDownloader ei käynnisty, joten salattua konttilinkkiä (.dlc, .ccf, .rsdf) ei saa avattua lainkaan. Aseta JAVA_HOME, tai osoita KL_JD johonkin muualla ajossa olevaan JDownloaderiin.',
  'settings.diagnostics.fix.javaNotNeeded': 'Tämä instanssi ei käynnistä omaa Java-prosessia: joko KL_JD osoittaa muualla ajossa olevaan JDownloaderiin, tai yksityinen on kytketty pois päältä asetuksella KL_PROVISION_JD=0.',
  'settings.diagnostics.fix.ytdlpMissing': 'yt-dlp ei löytynyt (KL_YTDLP, tai ”yt-dlp” PATH-polulla). Mediasivut kaatuvat silloin sivuston omaan virheeseen sen sijaan, että ne ladattaisiin.',
  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg ei löytynyt. yt-dlp tarvitsee sitä yhdistämään erilliset kuva- ja ääniraidat, joita useimmat sivustot jakavat, joten lataus jää toiseen niistä tai tulee takaisin ilman ääntä.',
  'settings.diagnostics.fix.ffprobeMissing': 'ffprobe ei löytynyt. Vain valmiin videon pituustarkistus käyttää sitä, kaikki muu toimii ilman.',
  'settings.diagnostics.fix.notRunnable': 'Löytyi polusta {subject}, eikä se lähtenyt käyntiin: {error}',
  'settings.diagnostics.fix.appearedLate': 'Se toimii nyt, eikä sitä ollut tämän instanssin käynnistyessä, joten sille ei ohjata vielä mitään. Ota se käyttöön käynnistämällä uudelleen.',
  'settings.diagnostics.fix.utcFallback': 'TZ on asetettu arvoon {subject}, eikä tämä instanssi saanut ladattua tuota vyöhykettä, joten se putosi takaisin UTC:hen kertomatta siitä missään. Jokainen aikatauluikkuna kulkee UTC-ajassa, kunnes tämä on korjattu. Tarkista kirjoitusasu vyöhykelistaa vasten (”Europe/Berlin”) ja se, onko imagessa ylipäätään vyöhyketietokantaa.',
  'settings.diagnostics.fix.noZoneDatabase': 'Tässä järjestelmässä ei ole vyöhyketietokantaa, joten ajat luetaan täysin ilman kesäaikasiirtymiä. Öinen ikkuna pitää talvisen tuntinsa läpi koko kesän, eikä kukaan kerro siitä, kun niin käy.',
  'settings.diagnostics.fix.tzUnset': 'TZ ei ole asetettu eikä paikallisaikaa löytynyt, joten tämä instanssi käy UTC-ajassa. Se toimii, ja se on hyvä tietää: aikatauluikkuna, johon on kirjoitettu 23:00, tarkoittaa kello 23:00 UTC-aikaa, ei kello 23:00 siellä missä sinä olet.',
  'settings.resolvers.toolsTitle': 'Työkalut',
  'settings.resolvers.toolsHint': 'yt-dlp lukee mediasivun, ffmpeg yhdistää raidat, jotka siitä tulevat. Molemmat ovat omia ohjelmiaan, jotka KnightLoader käynnistää, eikä kumpikaan ole osa tätä buildia. Siksi niiden versiot ovat tietämisen arvoisia: vanhentunut yt-dlp on yleisin syy siihen, että medialinkki, joka toimi viime kuussa, lakkaa toimimasta.',
  'settings.resolvers.toolsInUse': 'Käytössä',
  'settings.resolvers.toolsNotFound': 'Ei löytynyt',
  'settings.resolvers.toolsFrom.managed': 'KnightLoaderin oma kopio',
  'settings.resolvers.toolsFrom.env': 'KL_YTDLP',
  'settings.resolvers.toolsFrom.path': 'Löytyi PATH-polulta',
  'settings.resolvers.toolsFrom.none': 'Ei mistään',
  'settings.resolvers.toolsYtdlpMissingHint': 'Ilman yt-dlp:tä medialatauksille ei ole taustaohjelmaa lainkaan: linkki videosivulle hylätään sivuston omalla virheellä sen sijaan, että se ladattaisiin. Kontissa se tulee imagen yt-dlp-paketista, työpöydällä asennat sen itse ja joko laitat sen PATH-polulle tai osoitat KL_YTDLP siihen. Alla oleva painike hakee oman kopion, jos kumpikaan ei käy.',
  'settings.resolvers.toolsFfmpegMissingHint': 'Ilman ffmpegiä yt-dlp ei voi yhdistää erillisiä kuva- ja ääniraitoja, joita useimmat sivustot jakavat, joten lataus joko laskeutuu mykkänä videoraitana tai kaatuu kokonaan. Ilman ffprobea tämän sivun yläosassa oleva ”Mittaa valmis tiedosto” ei mittaa mitään eikä kerro siitä mitään. Kontissa molemmat tulevat ffmpeg-paketista, jonka image asentaa, työpöydällä asennat ne itse ja laitat ne PATH-polulle.',
  'settings.resolvers.toolsShadowed': 'Käynnissä on KnightLoaderin oma kopio. Niin kauan kuin se on siellä, KL_YTDLP:tä ja PATH-polkua ei käynnistetä: niiden sijaan käytettäisiin polkua {path}, ja se ilmoittaa version {version}.',
  'settings.resolvers.toolsShadowedOlder': 'Varo: kopio, jonka KnightLoader haki ({current}), on vanhempi kuin se, joka tällä koneella jo on ({system}, polussa {path}). Konttipäivitys tuo mukanaan uudemman yt-dlp:n, eikä oma kopiosi liiku sen mukana. Hae uusi, tai palaa järjestelmän kopioon.',
  'settings.resolvers.toolsManagedBroken': 'Polkuun {path} on kirjattu haettu kopio, eikä se käynnisty. Sen sijaan on käynnissä yllä näkyvä varavaihtoehto. Hae se uudelleen, tai palaa järjestelmän kopioon.',
  'settings.resolvers.toolsActions': 'yt-dlp:n pitäminen ajan tasalla',
  'settings.resolvers.toolsActionsHint': 'Hakeminen lataa yt-dlp:n osoitteesta github.com, tarkistaa sen samassa julkaisussa julkaistua SHA2-256SUMS-tiedostoa vasten, käynnistää sen kerran nähdäkseen, että se ylipäätään toimii tällä koneella, ja laittaa sen vasta sitten datasi viereen, mistä KnightLoader sen käynnistää. Tuohon viimeiseen vaiheeseen asti se kopio, joka sinulla jo oli, toimii edelleen, eikä järjestelmäsi omaan yt-dlp:hen kosketa koskaan.',
